1	/**
2	 * Fixed-width window aggregation over stored samples.
3	 */
4	
5	import type { MemoryStore } from "./store.ts";
6	import type { Sample } from "./validate.ts";
7	
8	export interface Window {
9	  /** Inclusive lower bound, epoch ms, aligned to a multiple of windowMs. */
10	  from: number;
11	  /** Exclusive upper bound, epoch ms. */
12	  to: number;
13	  count: number;
14	  sum: number;
15	  min: number;
16	  max: number;
17	}
18	
19	/** The aligned window start containing `at`. */
20	export function windowStart(at: number, windowMs: number): number {
21	  return Math.floor(at / windowMs) * windowMs;
22	}
23	
24	/**
25	 * Bucket samples into aligned windows. Empty windows are omitted rather than
26	 * emitted as zeroes — a gap is a gap, not a measurement of zero.
27	 */
28	export function windowsFor(samples: Sample[], windowMs: number): Window[] {
29	  if (!Number.isInteger(windowMs) || windowMs <= 0) {
30	    throw new RangeError("windowMs must be a positive integer");
31	  }
32	  const byStart = new Map<number, Window>();
33	
34	  for (const sample of samples) {
35	    const from = windowStart(sample.at, windowMs);
36	    let window = byStart.get(from);
37	    if (window === undefined) {
38	      window = {
39	        from,
40	        to: from + windowMs,
41	        count: 0,
42	        sum: 0,
43	        min: sample.value,
44	        max: sample.value,
45	      };
46	      byStart.set(from, window);
